package dev.nihit.gitdash.config;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import static org.assertj.core.api.Assertions.*;
class ConfigEditorTest{@TempDir Path temp;@Test void addsUpdatesAndRemovesOnlyAliasSection()throws Exception{Path file=temp.resolve("config.toml");Files.writeString(file,"[groups]\ndemo = [\"x\"]\n");ConfigEditor.putAlias(file,"demo",Path.of("/tmp/one"));ConfigEditor.putAlias(file,"demo",Path.of("/tmp/two"));assertThat(Files.readString(file)).contains("[aliases]").contains("demo = \"/tmp/two\"").contains("demo = [\"x\"]");assertThat(ConfigEditor.removeAlias(file,"demo")).isTrue();assertThat(Files.readString(file)).contains("demo = [\"x\"]").doesNotContain("/tmp/two");assertThat(ConfigEditor.removeAlias(file,"demo")).isFalse();}}
